import StopIcon from '@jetbrains/icons/stop.svg'
import {ControlsHeight} from '@jetbrains/ring-ui-built/components/global/controls-height'
import Tooltip from '@jetbrains/ring-ui-built/components/tooltip/tooltip'
import {IconButton} from '@jetbrains/teamcity-ui/dist/components'
import merge from 'lodash/merge'
import {useEffect, useMemo} from 'react'
import {graphql, useFragment, useMutation} from 'react-relay'

import {usePermission} from '../../../../../hooks/usePermission'
import {getBuildStatusTypeFromBuild} from '../../../../../selectors'
import {restApi} from '../../../../../services/rest'
import {Permission} from '../../../../../types'
import {subscribeOnRunningBuild} from '../../../../../utils/subscriber'
import {StatusBadge, TimeBadge as AdvancedTimeBadge} from '../../../../common/Badges'
import {EntityType} from '../../../../common/Badges/StatusBadge/StatusBadge.consts'
import {formatBuildNumber} from '../../../../common/BuildNumber/BuildNumber.utils'
import RunButton from '../../../../common/RunPipelineButton/RunPipelineButton'
import PersonalBuildStatusIcon from '../../../BuildPage/BuildPageHeader/PersonalBuildStatusIcon/PersonalBuildStatusIcon'
import {BranchBadge, RepositoryBadge, TriggeredByBadge} from '../../components/Badges'
import {useRunRepositoryBadge} from '../../components/Badges/RepositoryBadge/RepositoryBadge.hooks'
import Header from '../../components/Header/Header'
import {useJobId} from '../../EditPipelinePage/EditPipelinePage.hooks'
import {usePipelineHead} from '../../hooks/pipeline'
import {isPipelinesEnabledInExclusiveMode} from '../../utils/featureToggles'
import {usePipelineRunArg, usePipelineRunSettingJobIdMap} from '../PipelineRunPage.hooks'

import type {PipelineRunHeaderCancelBuildMutation} from './__generated__/PipelineRunHeaderCancelBuildMutation.graphql'
import type {PipelineRunHeaderFragment$key} from './__generated__/PipelineRunHeaderFragment.graphql'
import {useDurationInfo} from './PipelineRunHeader.hooks'

import styles from './PipelineRunHeader.module.css'

import {useAppDispatch} from 'src/hooks/react-redux'

const fragment = graphql`
  fragment PipelineRunHeaderFragment on PipelineRest {
    headBuildType {
      projectId
      ...pipelineHeadBuildTypeFragment
    }
  }
`

const cancelBuildMutation = graphql`
  mutation PipelineRunHeaderCancelBuildMutation($buildLocator: String!) {
    cancelBuild(buildLocator: $buildLocator, input: {}) {
      id
    }
  }
`

type Props = {pipelineKey: PipelineRunHeaderFragment$key | null}
function PipelineRunHeader({pipelineKey}: Props) {
  const isExclusiveMode = isPipelinesEnabledInExclusiveMode()
  const arg = usePipelineRunArg()
  const {run, parallelized} = restApi.endpoints.getBuildNormalized.useQuery(arg, {
    selectFromResult: ({data}) => {
      const {entities, result} = data ?? {}
      const {builds} = entities ?? {}
      const run = builds?.[result!]
      const jobs = run?.['snapshot-dependencies']?.build
      return {
        run,
        parallelized: jobs?.some(job => job.parallelized),
      }
    },
  })
  const jobIdMap = usePipelineRunSettingJobIdMap()
  const {id, number, state, branchName, defaultBranch, triggered} = run ?? {}
  const isQueued = state === 'queued'
  const runNumber = formatBuildNumber({number}).text
  const runStatusType = getBuildStatusTypeFromBuild(run)
  const dispatch = useAppDispatch()
  const currentJobId = Number(useJobId())
  const currentBuildTypeName = jobIdMap?.get(currentJobId)
  const pipeline = useFragment(fragment, pipelineKey)
  const {headBuildType: pipelineHeadBuildTypeKey = null} = pipeline ?? {}
  const head = usePipelineHead(pipelineHeadBuildTypeKey)

  const isRunning = state === 'running'

  useEffect(() => {
    if (id != null && isRunning) {
      return subscribeOnRunningBuild(id, data =>
        dispatch(
          restApi.util.updateQueryData('getBuildNormalized', arg, draft => {
            const draftRun = draft?.entities?.builds?.[draft?.result!]

            merge(draftRun, data)
          }),
        ),
      )
    }
    return undefined
  }, [arg, dispatch, id, isRunning])

  const [cancelBuild, isCancelling] =
    useMutation<PipelineRunHeaderCancelBuildMutation>(cancelBuildMutation)

  const projectId = pipeline?.headBuildType?.projectId
  const canCancel = usePermission(Permission.CANCEL_BUILD, projectId)

  const {duration, optimized, queue, timeLeft, isLoading, optimizations, possibleOptimizations} =
    useDurationInfo(id, parallelized)
  const {displayedRepo, additionalRepos, vcsProviderType} = useRunRepositoryBadge()
  const badges = useMemo(
    () => (
      <>
        <StatusBadge status={runStatusType} isRunning={isRunning} type={EntityType.PIPELINE} />
        <BranchBadge branchName={branchName} />
        <AdvancedTimeBadge
          className={styles.runTimeBadge}
          duration={duration}
          queueDuration={queue}
          estimatedDuration={timeLeft}
          optimizedDuration={optimized}
          withAppliedOptimizations={!!optimizations?.length}
          isRunning={isRunning}
          isQueued={isQueued}
          isLoading={isLoading}
          optimizations={optimizations}
          possibleOptimizations={possibleOptimizations}
          hasNoRuns={false}
          clickable={!isQueued}
        />
        <RepositoryBadge
          displayedRepo={displayedRepo}
          additionalRepos={additionalRepos}
          vcsProviderType={vcsProviderType}
        />
        <TriggeredByBadge triggered={triggered} />
      </>
    ),
    [
      additionalRepos,
      branchName,
      displayedRepo,
      duration,
      isLoading,
      isQueued,
      isRunning,
      optimizations,
      optimized,
      possibleOptimizations,
      queue,
      runStatusType,
      timeLeft,
      triggered,
      vcsProviderType,
    ],
  )

  const actions = useMemo(
    () => (
      <>
        {state !== 'finished' && (isExclusiveMode || (!isExclusiveMode && canCancel)) && (
          <Tooltip
            title={
              canCancel
                ? undefined
                : `You don't have permission to ${isRunning ? 'stop' : 'cancel'} this run`
            }
          >
            <IconButton
              danger
              withBorder
              className={styles.stopButton}
              height={ControlsHeight.M}
              icon={StopIcon}
              loader={isCancelling}
              disabled={!canCancel}
              title={isRunning ? 'Stop run' : 'Cancel run'}
              onClick={() => cancelBuild({variables: {buildLocator: `id:${id}`}})}
            />
          </Tooltip>
        )}
        <RunButton
          primary
          className={styles.button}
          branchName={defaultBranch ? undefined : branchName}
          hasVcsRoot={displayedRepo != null}
          headId={head?.id}
          projectId={head?.projectId}
        />
      </>
    ),
    [
      branchName,
      canCancel,
      cancelBuild,
      defaultBranch,
      displayedRepo,
      head?.id,
      head?.projectId,
      id,
      isCancelling,
      isExclusiveMode,
      isRunning,
      state,
    ],
  )

  if (run == null) {
    return null
  }

  return (
    <Header
      pipelineHeadBuildTypeKey={pipelineHeadBuildTypeKey}
      icon={run.personal && <PersonalBuildStatusIcon buildId={run.id} isQueued={isQueued} />}
      title={isQueued ? `In queue` : `Run ${runNumber}`}
      contentClassName={styles.badges}
      content={badges}
      actions={actions}
      preservedQueryParams={currentBuildTypeName != null ? `job=${currentBuildTypeName}` : ``}
      hasVcsRoot={displayedRepo != null}
      showBottomBorder={false}
    />
  )
}

export default PipelineRunHeader
