import exceptionIcon from '@jetbrains/icons/exception.svg'
import lockIcon from '@jetbrains/icons/lock.svg'
import ErrorMessage from '@jetbrains/ring-ui-built/components/error-message/error-message'
import {Suspense, useMemo} from 'react'
import type {EntryPointProps} from 'react-relay'
import {EntryPointContainer, usePreloadedQuery} from 'react-relay'

import {getPipelinesHref} from '../../../../routes'
import Loader from '../../../common/Loader/Loader'
import RouterLink from '../../../common/RouterLink/RouterLink'
import FullScreenErrorWrapper from '../components/FullScreenErrorWrapper/FullScreenErrorWrapper'
import type {EditPipelinePageEntryPoint} from '../EditPipelinePage/EditPipelinePage.entryPoint'
import {serializeError} from '../utils/error'

import type {PipelineRunPagePipelineQuery} from './__generated__/PipelineRunPagePipelineQuery.graphql'
import type {PipelineRunContentEntryPoint} from './PipelineRunContent/PipelineRunContent.entryPoint'
import PipelineRunHeader from './PipelineRunHeader/PipelineRunHeader'
import {usePipelineRunPage} from './PipelineRunPage.hooks'
import {pipelineQuery} from './PipelineRunPage.queries'

type Queries = {pipeline: PipelineRunPagePipelineQuery}
export type NestedEntryPoints = {
  pipelineRunContent?: typeof PipelineRunContentEntryPoint
  editPipelineContent?: typeof EditPipelinePageEntryPoint
}
function PipelineRunPage({
  queries,
  entryPoints,
}: EntryPointProps<Queries, NestedEntryPoints, {}, {}>) {
  const {pipeline = null} = usePreloadedQuery(pipelineQuery, queries.pipeline)
  const {jobId, buildError, pipelineError, isPageDataLoading, isEdit, canViewPipelineSettings} =
    usePipelineRunPage()

  const content = useMemo(
    () => (
      <Suspense fallback={<Loader />}>
        {isEdit && entryPoints.editPipelineContent && (
          <EntryPointContainer entryPointReference={entryPoints.editPipelineContent} props={{}} />
        )}
        {!isEdit && entryPoints.pipelineRunContent && (
          <EntryPointContainer
            entryPointReference={entryPoints.pipelineRunContent}
            props={{jobId}}
          />
        )}
      </Suspense>
    ),
    [entryPoints.editPipelineContent, entryPoints.pipelineRunContent, isEdit, jobId],
  )

  if (isEdit && !canViewPipelineSettings) {
    return (
      <FullScreenErrorWrapper>
        <ErrorMessage
          icon={lockIcon}
          message="Access denied"
          description="You do not have enough permissions to view this pipeline's settings"
        >
          <RouterLink to={getPipelinesHref()}>{'Go to the home page'}</RouterLink>
        </ErrorMessage>
      </FullScreenErrorWrapper>
    )
  }

  if (isPageDataLoading) {
    return <Loader />
  }

  const error = buildError ?? pipelineError
  if (error) {
    return (
      <FullScreenErrorWrapper>
        <ErrorMessage
          icon={exceptionIcon}
          message="Error while loading pipeline"
          description={serializeError(error)}
        >
          <RouterLink to={getPipelinesHref()}>{'Go to the home page'}</RouterLink>
        </ErrorMessage>
      </FullScreenErrorWrapper>
    )
  }

  return (
    <>
      <PipelineRunHeader pipelineKey={pipeline} />
      {content}
    </>
  )
}

export default PipelineRunPage
export type PipelineRunPageComponent = typeof PipelineRunPage
