import {skipToken} from '@reduxjs/toolkit/query'
import {useEffect} from 'react'

import {subscribeOnBuild} from '../../../../../actions/builds'
import {useAppDispatch, useAppSelector} from '../../../../../hooks/react-redux'
import {getBuild} from '../../../../../selectors'
import type {BuildId} from '../../../../../types'
import {
  useOptimizations,
  useRunDuration,
  useRunRemainingTime,
  useTimeInQueue,
} from '../../../../common/Badges/TimeBadge/TimeBadge.hooks'
import {usePipelineId} from '../../hooks/pipeline'
import {pipelinesApi} from '../../services/pipelinesApi'

export function useDurationInfo(runId?: BuildId, parallelized?: boolean) {
  const pipelineId = usePipelineId()
  const dispatch = useAppDispatch()

  const runState = useAppSelector(state => getBuild(state, runId)?.state)

  const isRunning = runState === 'running'
  const isFinished = runState === 'finished'

  const duration = useRunDuration(runId)
  const timeLeft = useRunRemainingTime(runId)

  const {data, isLoading} = pipelinesApi.endpoints.getRunOptimizations.useQuery(
    isFinished && runId ? {pipelineId, runId} : skipToken,
    {
      selectFromResult: ({data, isLoading}) => ({
        data,
        isLoading,
      }),
    },
  )

  useEffect(() => {
    if (runId != null && isRunning) {
      return dispatch(subscribeOnBuild(runId))
    }
    return undefined
  }, [runId, isRunning, dispatch])

  const {optimizedDuration, appliedOptimizations} = data ?? {}

  const queue = useTimeInQueue(runId)
  const optimized = Number(optimizedDuration)

  const {optimizations, possibleOptimizations} = useOptimizations(
    appliedOptimizations,
    parallelized,
  )

  return {
    duration,
    optimized,
    queue,
    timeLeft,
    isLoading,
    optimizations,
    possibleOptimizations,
  }
}
