import Tooltip from '@jetbrains/ring-ui-built/components/tooltip/tooltip'
import classNames from 'classnames'

import {useBuildStatusIcon} from '../../../../../hooks/useBuildStatusIcon'
import {useBuildPrefix} from '../../../../../hooks/useBuildStatusTooltip'
import type {BuildId} from '../../../../../types'
import Icon from '../../../../common/Icon/Icon'

import styles from './PersonalBuildStatusIcon.module.css'

type Props = {
  buildId: BuildId
  isQueued: boolean
}

function PersonalBuildStatusIcon({buildId, isQueued}: Props) {
  const statusTooltip = useBuildPrefix(buildId)
  const statusIcon = useBuildStatusIcon(buildId)
  const statusIconClassNames = classNames(styles.statusIcon, {
    [styles.personalQueuedIcon]: isQueued,
  })

  return (
    <Tooltip delay={500} title={statusTooltip}>
      <Icon name={statusIcon} className={statusIconClassNames} size="M" />
    </Tooltip>
  )
}
export default PersonalBuildStatusIcon
