import {useMemo, useEffect} from 'react'

import {usePipelineId} from '../../../hooks/pipeline'
import {usePipelineRunArg} from '../../../PipelineRunPage/PipelineRunPage.hooks'
import {mainVcsRootIdSuffix} from '../../../PipelinesPages.consts'
import {pipelinesApi} from '../../../services/pipelinesApi'
import {VcsProviderType} from '../../../services/pipelinesApi.types'
import {getRepositoryNameFromVcsRoot} from '../../../utils/vcs'

import {restApi} from 'src/services/rest'
import {subscribeOnBuildTypeEvents} from 'src/utils/subscriber'
import {BUILD_CHANGES_LOADED} from 'src/utils/subscriptionEvents'

export const useRunRepositoryBadge = () => {
  const pipelineId = usePipelineId()
  const arg = usePipelineRunArg()
  const {isQueued, isRunning, headInternalId, runId} =
    restApi.endpoints.getBuildNormalized.useQuery(arg, {
      selectFromResult: ({data}) => {
        const run = data?.entities?.builds?.[data?.result!]
        const headId = run?.buildType
        return {
          runId: run?.id,
          isQueued: run?.state === 'queued',
          isRunning: run?.state === 'running',
          headInternalId: data?.entities?.buildTypes?.[headId!]?.internalId,
        }
      },
    })
  const {data: vcsRoots, refetch} = pipelinesApi.endpoints.getPipelineRunVcsRoots.useQuery(
    {pipelineId, runId: runId!},
    {skip: runId == null},
  )
  const {mainRepo, additionalRepos} = useMemo(() => {
    const mainVcsRoot =
      vcsRoots?.find(vcsRoot => vcsRoot.id.endsWith(mainVcsRootIdSuffix)) ?? vcsRoots?.[0]
    const additionalRepos = vcsRoots
      ?.filter(vcsRoot => vcsRoot.id !== mainVcsRoot?.id)
      .map(vcsRoot => getRepositoryNameFromVcsRoot(vcsRoot))

    return {
      mainRepo:
        mainVcsRoot != null
          ? {
              name: getRepositoryNameFromVcsRoot(mainVcsRoot, true),
              vcsProviderType: mainVcsRoot.isExternal
                ? VcsProviderType.EXISTING_VCS_ROOT
                : mainVcsRoot.vcsProviderType,
            }
          : null,
      additionalRepos,
    }
  }, [vcsRoots])

  useEffect(() => {
    if (headInternalId != null && (isQueued || isRunning)) {
      return subscribeOnBuildTypeEvents(headInternalId, [BUILD_CHANGES_LOADED], refetch)
    }

    return undefined
  }, [headInternalId, isQueued, isRunning, refetch])

  return {
    displayedRepo: mainRepo?.name,
    vcsProviderType: mainRepo?.vcsProviderType,
    additionalRepos,
  }
}
